(window["webpackJsonp"]=window["webpackJsonp"]||[]).push([["actividad"],{"0125":function(e,a,o){e.exports=o.p+"img/imagen4.ee615310.png"},4298:function(e,a,o){"use strict";o.r(a);var n=function(){var e=this,a=e._self._c;return a("div",{staticClass:"curso-main-container pb-3"},[a("BannerInterno",{attrs:{icono:"far fa-question-circle",titulo:"Actividad didáctica"}}),a("div",{staticClass:"container tarjeta tarjeta--blanca p-4 p-md-5"},[a("div",{attrs:{id:"Actividad"}},[a("Actividad",{attrs:{cuestionario:e.cuestionario}})],1)])],1)},i=[],s={name:"ActividadDidactica",data:()=>({cuestionario:{tema:"Procedimiento de la valoración de apoyos",titulo:"Cuestionario",introduccion:"<b>Objetivo:</b> identificar la apropiación de los conocimientos sobre accesibilidad, ajustes razonables, caja de herramientas y formatos.",barajarPreguntas:!0,preguntas:[{id:1,texto:"¿Todas las personas con discapacidad requieren una valoración de apoyos para ejercer su derecho a decidir de manera autónoma, segura y con los ajustes razonables que puedan necesitar?",imagen:o("b3a4"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Sí, porque al tener alguna discapacidad requieren ajustes razonables que faciliten la toma de decisiones.",esCorrecta:!1},{id:"b",texto:"No, porque no todas las personas con discapacidad necesitan apoyos para tomar decisiones de forma autónoma y segura.",esCorrecta:!0},{id:"c",texto:"Sí, porque como medida de protección se valora el tipo de apoyo que les permita decidir con seguridad y confianza.",esCorrecta:!1},{id:"d",texto:"Si, porque todas las personas con discapacidad, sin excepción, no tienen capacidad jurídica para la toma de decisiones.",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:2,texto:"¿Una persona con discapacidad auditiva necesita una valoración de apoyos para ejercer su derecho a decidir de manera autónoma y con acceso pleno a la información?",imagen:o("6a9b"),barajarRespuestas:!0,opciones:[{id:"a",texto:"No, solo requiere ajustes razonables que faciliten la comunicación y el acceso pleno a la información.",esCorrecta:!0},{id:"b",texto:"Sí, porque las personas sordas enfrentan barreras comunicativas que dificultan ejercer decisiones de manera adecuada.",esCorrecta:!1},{id:"c",texto:"Sí, porque al tener una discapacidad, pueden requerir valoración de apoyos para que otra persona les ayude a decidir con respaldo jurídico.",esCorrecta:!1},{id:"d",texto:"No, porque las personas con discapacidad auditiva no requieren ajustes razonables, ya que se pueden desplazar autónomamente.",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:3,texto:"¿Todas las personas con discapacidad intelectual requieren una valoración de apoyos para ejercer su derecho a decidir sobre distintos aspectos de la vida de forma autónoma, informada y segura?",imagen:o("b70f"),barajarRespuestas:!0,opciones:[{id:"a",texto:"No, solo en algunos casos se realiza valoración de apoyos para facilitar decisiones informadas sobre aspectos puntuales de la vida.",esCorrecta:!0},{id:"b",texto:"Siempre se requiere valoración de apoyos para que otra persona respalde decisiones sobre todos los aspectos de la vida.",esCorrecta:!1},{id:"c",texto:"Sí, se necesita valoración de apoyos para acceder a adjudicación judicial que permita a otra persona tomar decisiones por ellas.",esCorrecta:!1},{id:"d",texto:"Sí, las personas con discapacidad intelectual requieren de un proceso de interdicción, para que una persona de confianza pueda ayudarles a tomar decisiones.",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:4,texto:"Cuando se realiza una valoración de apoyos, debe tenerse en cuenta:",imagen:o("0125"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Una entrevista semiestructurada general.",esCorrecta:!1},{id:"b",texto:"Una entrevista grupal.",esCorrecta:!1},{id:"c",texto:"Una entrevista semiestructurada individual.",esCorrecta:!0},{id:"d",texto:"Una entrevista estructurada vecinal.",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:5,texto:"El consentimiento informado es:",imagen:o("e111"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Un documento que firma la persona con discapacidad de manera posterior a la valoración de apoyos.",esCorrecta:!1},{id:"b",texto:"Un documento que firma la familia de manera posterior a la valoración de apoyos.",esCorrecta:!1},{id:"c",texto:"Un documento que firma la persona con discapacidad para su entrevista de valoración de apoyos.",esCorrecta:!0},{id:"d",texto:"Un documento que firma la familia para establecer una red de posibles apoyos.",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:6,texto:"¿Qué se debe considerar para implementar ajustes razonables que garanticen el ejercicio pleno de los derechos?",imagen:o("b3a4"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Un ajuste específico según el tipo de discapacidad que presente la persona con discapacidad.",esCorrecta:!1},{id:"b",texto:"Ajustes diversos que respondan a necesidades particulares, siempre que la persona los solicite de forma voluntaria.",esCorrecta:!0},{id:"c",texto:"Un diagnóstico de acuerdo con el Sistema Internacional de Enfermedades Mentales (CIE 11).",esCorrecta:!1},{id:"d",texto:"La historia clínica como referencia para identificar los antecedentes de salud en cada caso.",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:7,texto:"¿Qué es un ajuste razonable para garantizar el ejercicio pleno de derechos de las personas con discapacidad en igualdad de condiciones?",imagen:o("6a9b"),barajarRespuestas:!0,opciones:[{id:"a",texto:"La implementación y uso de herramienta tecnológica que facilite la interacción con personas con discapacidad en contextos específicos y necesarios.",esCorrecta:!1},{id:"b",texto:"Modificaciones y adaptaciones necesarias y adecuadas que no generen carga excesiva y garanticen derechos en igualdad de condiciones con otras personas.",esCorrecta:!0},{id:"c",texto:"Estrategia que permite a personas con discapacidad tomar decisiones informadas, seguras y respetadas en distintos ámbitos de vida.",esCorrecta:!1},{id:"d",texto:"Modificaciones en las rutinas de las personas con discapacidad y que le permitan acceder a los diferentes servicios.",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{texto:"El principio que establece que el derecho a la accesibilidad no puede dividirse ni aplicarse parcialmente, y que garantiza este derecho para todas las personas con discapacidad sin distinción, se denomina:",imagen:o("b70f"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Principio de indivisibilidad",esCorrecta:!0},{id:"b",texto:"Principio de interdependencia",esCorrecta:!1},{id:"c",texto:"Principio de progresividad",esCorrecta:!1},{id:"d",texto:"Principio de dependencia",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:9,texto:"Desde el principio de interdependencia, ¿cuál afirmación refleja correctamente la relación entre el derecho al trabajo y el derecho a la accesibilidad para personas con discapacidad?",imagen:o("0125"),barajarRespuestas:!0,opciones:[{id:"a",texto:"El derecho al trabajo y el derecho a la accesibilidad son independientes y tienen sus propias particularidades y formas de garantizarse.",esCorrecta:!1},{id:"b",texto:"El derecho al trabajo y el derecho a la accesibilidad se amplían progresivamente en el tiempo, según nuevas normatividades vigentes.",esCorrecta:!1},{id:"c",texto:"El derecho al trabajo y el derecho a la accesibilidad implican realizar procesos educativos con quienes valoran los apoyos requeridos.",esCorrecta:!1},{id:"d",texto:"El derecho al trabajo y el derecho a la accesibilidad se entrelazan, convirtiéndose en una sola garantía.",esCorrecta:!0}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:10,texto:"¿Qué distingue a los ajustes razonables de los ajustes procesales en el ejercicio de derechos de las personas con discapacidad?",imagen:o("e111"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Los ajustes razonables se aplican en contextos judiciales; los ajustes procesales garantizan acceso a la información y comunicación general.",esCorrecta:!1},{id:"b",texto:"Los ajustes razonables permiten adaptarse a las necesidades de la red de apoyo de las personas con discapacidad; los procesales son meramente instrumentales.",esCorrecta:!1},{id:"c",texto:"Los ajustes razonables garantizan acceso a la información, comunicación y entornos físicos; los procesales se aplican en contextos judiciales o administrativos.",esCorrecta:!1},{id:"d",texto:"Los ajustes razonables permiten identificar las necesidades de las personas con discapacidad; los procesales realizar las adaptaciones respectivas en cualquier entorno físico o institucional.",esCorrecta:!0}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:11,texto:"¿Cuál de las siguientes acciones corresponde a los mínimos para el acercamiento con las personas con discapacidad psicosocial en las valoraciones de apoyo?",imagen:o("b3a4"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Actuar de manera natural, empleando un lenguaje igual al que se usa con las demás personas, sin modificar tono ni forma.",esCorrecta:!0},{id:"b",texto:"Hablar con un lenguaje infantilizado para facilitar la comprensión de la persona y acorde con su nivel intelectual y capacidad comunicativa.",esCorrecta:!1},{id:"c",texto:"Evitar en la medida de lo posible el contacto directo para evitar incomodar a la persona y su red de apoyo.",esCorrecta:!1},{id:"d",texto:"Dirigir la conversación únicamente a la red de apoyo de la persona, pues solo esta puede explicar el proceso cabalmente.",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:12,texto:"Recursos humanos como docentes, intérpretes y modelos lingüísticos garantizan comunicación, información y aprendizaje accesible para personas con discapacidad en condiciones de equidad:",imagen:o("6a9b"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Tecnologías y productos de apoyo",esCorrecta:!1},{id:"b",texto:"Recursos pedagógicos",esCorrecta:!1},{id:"c",texto:"Recursos comunicativos",esCorrecta:!0},{id:"d",texto:"Recursos especializados",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:13,texto:"El derecho a la accesibilidad se fundamenta en los principios de universalidad, indivisibilidad e interdependencia, progresividad, igualdad y no discriminación.",imagen:o("b70f"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Verdadero",esCorrecta:!0},{id:"b",texto:"Falso",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:14,texto:"Al entrevistar a una persona con discapacidad intelectual grave, es adecuado asegurar la accesibilidad de los materiales, utilizar lenguaje claro y herramientas visuales, verificar la comprensión y explorar sus intereses, motivaciones y apoyos necesarios.",imagen:o("0125"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Verdadero",esCorrecta:!0},{id:"b",texto:"Falso",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:15,texto:"¿Cuáles afirmaciones describen adecuadamente algunos aspectos del uso del Personal Map como herramienta aplicable en valoraciones de apoyo para personas con discapacidad?",imagen:o("e111"),barajarRespuestas:!0,opciones:[{id:"a",texto:"El Personal Map permite identificar gustos, motivaciones, sueños y objetivos, facilitando una conversación centrada en la persona entrevistada.",esCorrecta:!0},{id:"b",texto:"El Personal Map se utiliza exclusivamente para evaluar habilidades cognitivas y no aborda intereses, motivaciones, sueños ni metas personales.",esCorrecta:!1},{id:"c",texto:"El Personal Map permite conocer aspectos esenciales de la persona: intereses, metas y apoyos necesarios para alcanzarlos plenamente.",esCorrecta:!0},{id:"d",texto:"El Personal Map es una técnica verbal que excluye elementos visuales y no considera los sueños, motivaciones ni aspiraciones personales.",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:16,texto:"La accesibilidad, vista desde el principio de la universalidad, está pensada para todos (as, es), en este caso el para todos (as, es) dependerá si la persona tiene algún tipo de discapacidad. La universalidad no es un derecho que todos los seres humanos del planeta tengan, este responde a una necesidad.",imagen:o("b3a4"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Verdadero",esCorrecta:!0},{id:"b",texto:"Falso",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:17,texto:"Los recursos y apoyos orientados a fortalecer la autonomía, la independencia y la toma de decisiones de las personas con discapacidad pueden ser de orden tecnológico, pedagógico o una combinación de ambos.",imagen:o("6a9b"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Verdadero",esCorrecta:!0},{id:"b",texto:"Falso",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:18,texto:"Las personas con discapacidad son nombradas así, porque ellas mismas decidieron que este término era pertinente porque las hacía visibles en todos los escenarios de participación del mundo.",imagen:o("b70f"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Verdadero",esCorrecta:!0},{id:"b",texto:"Falso",esCorrecta:!1}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:19,texto:"Una persona sin discapacidad que trabaja en un tercer piso sin ascensor puede exigir legalmente la instalación de una rampa o elevador por motivos de accesibilidad.",imagen:o("0125"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Verdadero",esCorrecta:!1},{id:"b",texto:"Falso",esCorrecta:!0}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."},{id:20,texto:"La caja de herramientas tiene como propósito evaluar a las personas con discapacidad sin necesidad de estrategias, recursos ni acciones afirmativas por parte de las personas facilitadoras del proceso de valoración.",imagen:o("e111"),barajarRespuestas:!0,opciones:[{id:"a",texto:"Verdadero",esCorrecta:!1},{id:"b",texto:"Falso",esCorrecta:!0}],mensaje_correcto:"Excelente trabajo. Tiene un claro entendimiento del componente.",mensaje_incorrecto:"Revise nuevamente el contenido del componente formativo."}],mensaje_final_aprobado:"Ha superado la actividad y demuestra sólidos conocimientos sobre el componente formativo.",mensaje_final_reprobado:"No ha superado la actividad. Le recomendamos volver a revisar el componente formativo e intentar nuevamente la actividad didáctica."}})},r=s,t=o("2877"),c=Object(t["a"])(r,n,i,!1,null,null,null);a["default"]=c.exports},"6a9b":function(e,a,o){e.exports=o.p+"img/imagen2.e56ee50c.png"},b3a4:function(e,a,o){e.exports=o.p+"img/imagen1.747dc6c7.png"},b70f:function(e,a,o){e.exports=o.p+"img/imagen3.81e4fb6d.png"},e111:function(e,a,o){e.exports=o.p+"img/imagen5.720eebe1.png"}}]);
